"""Write the current Alpha release from one exact tested standalone artifact."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[2];base=root/'output/elyndor/pixellab-v22'
def read(name):return json.loads((base/name).read_text(encoding='utf-8'))
reg=read('regression.json');source=json.loads((root/'output/elyndor/continuous-standalone-audit.json').read_text(encoding='utf-8'));sha=hashlib.sha256((root/'index.html').read_bytes()).hexdigest()
assert sha==reg['sha256']==source['sha256'] and source['sourceMatchesArtifact'] and not source['cropWarnings']
assert len(reg['checks'])==31 and all(q['pass']for q in reg['checks'])
features=read('revision/report.json');records=read('records/report.json');stairs=read('stairs/report.json');coached=read('coached/report.json');campaign=read('campaign/report.json');performance=read('performance/native.json');combat=read('combat-profile-final.json');atlas=read('atlas-performance.json');voices=read('audio-audit.json');sounds=read('soundtrack-audit.json');water=read('water/report.json');locations=read('locations/report.json');dry=read('soak-release-dry.json');storm=read('soak-release-storm.json')
assert all(q['pass']for q in[features,records,stairs,coached,atlas,voices,sounds,water,locations,dry,storm,performance])
assert campaign['campaign']['final']=='complete' and not campaign['errors'] and not campaign['voiceMissing']
assert not combat['newPrograms'] and combat['cpu']['p95']<25
transcripts=json.loads((root/'elyndor/audio/transcription-audit-v22.json').read_text(encoding='utf-8'));assert transcripts['clips']==49 and not transcripts['unresolvedWordDifferences']
assert all(q['hostMenu']and q['records']for q in features['inns'])
assert voices['clips']==259 and sounds['sounds']==93 and features['tutorial']['worldClips']==0 and features['tutorial']['plays']==0
catalogText=(root/'elyndor/title-v19.js').read_text(encoding='utf-8');catalog=json.loads(catalogText.split('const CHANGELOG19=',1)[1].split(';\n',1)[0]);assert len(catalog)==1 and catalog[0]['version']=='Alpha Version 1.0'
casting=json.loads((root/'elyndor/audio/catalog.json').read_text(encoding='utf-8'))['casting']['bren']
def soakSummary(q):return{'pass':q['pass'],'scope':q['scope'],'phases':[{k:x[k]for k in['label','drawFPS','render','tick','memory','liveHeap','scale','weather']}for x in q['phases']],'errors':q['errors']}
r={'release':'elyndor-alpha-1.0-2026-10-29-cinematic-v22','version':'Alpha Version 1.0','game':'The Last Light of Elyndor','artifact':{'file':'index.html','bytes':(root/'index.html').stat().st_size,'sha256':sha,'offline':True},'featureCatalogue':catalog[0],
'githubHistory':{'firstCommit':'8a061609410b54af58775c8bbeaab15981a55acc','firstDate':'2026-10-22','previousRelease':'8946a1172b79b374252e4c300f15405979178645'},
'changes':['Selective HDR highlight bloom uses two reusable quarter-resolution targets; depth-aware diorama focus preserves the party and softens foreground, distance and all four edges','Warm directional light, cooler soft shadows, earthy color grading and readable night combat fill refine the existing world lighting','Every outdoor POI and the overworld have moving cloud shadows plus world-cell-anchored, cloud-lit dust and fireflies; drift runs on the GPU','All 33 tutorial World voice recordings and replay-voice controls are removed; guided text, highlights, world arrows and scripted combat practice remain','A clear, original youthful Bren voice replaces the previous identity; all 49 story and combat performances are regenerated and pass spoken-word QA','All 15 POI entrances have accessible floor save seals using the existing three-slot save/load, overwrite and delete interface','Both inns retain chronicle circles and have explicit Rest and Journey records services; resting fully restores stat-based party HP and MP for 15 coins, advances to morning and writes one inn checkpoint','Stable static world transforms, visibility budgets, reflection scheduling and prewarmed effects are retained; no world texture or character art is replaced'],
'art':{'generator':'PixelLab','nativeSelectedFamilies':41,'runtimeFamilies':42,'packedSpritePoses':source['packedPoses'],'sourceCropWarnings':0,'newGeneratedAssets':0,'approvedConceptPaletteRetained':True},
'audio':{'provider':'ElevenLabs','recordedVoices':259,'soundAssets':93,'totalRecordings':352,'newBrenPerformances':49,'removedTutorialRecordings':33,'brenCasting':casting,'transcription':transcripts,'nativePlayback':features['voice'],'offline':True,'embeddedCredential':False},
'validation':{'checks':reg['checks'],'newFeatures':features,'titleAndRecords':records,'stairAndRiverRepairs':stairs,'coachedBattleRegression':coached,'locations':locations,'sourceMatchesArtifact':True,'storyProgressionSteps':len(campaign['campaign']['log']),'storyBattles':len(campaign['campaign']['battles']),'restoredLights':len(campaign['campaign']['restored']),'saveLoad':campaign['persistence'],'waterJoinMaxGapMetres':max(j['gap']for row in coached['water']for j in row['joins'])},
'performance':{'device':performance['device'],'nativeScenarios':performance['scenarios'],'repeatedDryPlay':soakSummary(dry),'repeatedStormPlay':soakSummary(storm),'pump':read('pump-fixed.json'),'tutorial':read('onboarding-performance.json'),'combatRenderCPU':combat['cpu'],'newCombatPrograms':len(combat['newPrograms']),'atlas':atlas,'scope':'Native Chrome 1440x900 on the recorded RTX 4080 device. Draw target follows monitor cadence, about 72 Hz here. Performance varies by hardware; retained heap GC is test-only.'}}
